css:
@page { size: A4; margin: 14mm; }

.print-format { font-family: "IBM Plex Sans Arabic", "Noto Sans Arabic", Arial, sans-serif; color: #111827; font-size: 11px; line-height: 1.5; }
.md-print-ref { direction: ltr; unicode-bidi: bidi-override; display: inline-block; font-variant-numeric: tabular-nums; }
.md-print-heading { width: 100%; border-bottom: 2px solid #1a375b; margin-bottom: 12px; }
.md-print-heading td { vertical-align: top; padding-bottom: 12px; }
.md-print-heading h2 { margin: 0 0 6px; font-size: 22px; color: #1a375b; }
.md-print-meta { width: 100%; margin: 12px 0 20px; }
.md-print-meta td { width: 50%; padding: 6px 10px; vertical-align: top; }
.md-print-muted { color: #566477; font-size: 10px; }
.md-print-items { width: 100%; border-collapse: collapse; }
.md-print-items th, .md-print-items td { padding: 9px; border: 1px solid #cbd5e1; text-align: start; vertical-align: top; overflow-wrap: anywhere; }
.md-print-items th { background: #eff2f5; font-weight: bold; }
.md-print-items thead { display: table-header-group; }
.md-print-items tr, .md-print-signatures { break-inside: avoid; page-break-inside: avoid; }
.md-print-signatures { width: 100%; margin-top: 36px; }
.md-print-signatures td { width: 50%; padding: 12px; }
.md-print-signature-line { border-top: 1px solid #566477; padding-top: 8px; margin-top: 32px; }
.md-print-qr { width: 24mm; height: 24mm; object-fit: contain; }

.print-format table { font-size: inherit; line-height: inherit; }
.md-print-items th { overflow-wrap: normal; word-break: normal; }
